def connected(pts):
    pts=set(pts)
    if not pts: return None
    seen={next(iter(pts))}; st=list(seen)
    while st:
        y,x=st.pop()
        for d in ((1,0),(-1,0),(0,1),(0,-1)):
            n=(y+d[0],x+d[1])
            if n in pts and n not in seen: seen.add(n); st.append(n)
    return len(seen)==len(pts)

