def rel_feats(p, R, C):
    feats={}
    for (i,j),pts in p.items():
        s=set(pts)
        f={'count':len(pts)}
        # alignment within panel
        ys=[y for y,x in pts]; xs=[x for y,x in pts]
        f['same_col']= len(set(xs))<len(pts) if pts else False
        f['same_row']= len(set(ys))<len(pts) if pts else False
        # match with neighbors' rel positions
        for name,(di,dj) in {'up':(-1,0),'down':(1,0),'left':(0,-1),'right':(0,1)}.items():
            nb=(i+di,j+dj)
            if nb in p:
                s2=set(p[nb])
                f['match_'+name]=len(s & s2)
            else: f['match_'+name]=None
        feats[(i,j)]=f
    return feats

